def forward(groups):
    date, spaces, time = groups
    dt = datetime.strptime(date + time, '%y%m%d%H%M%S')
    return {'stored': [int(dt.timestamp() * 1000000)], 'layout': [len(spaces)]}

def inverse(record):
    micros = int(record['stored'][0])
    spaces_count = record['layout'][0]
    dt = datetime.fromtimestamp(micros / 1000000)
    return dt.strftime('%y%m%d') + (' ' * spaces_count) + dt.strftime('%H%M%S')
